<?php
/**
 * Compatible editorial refinements for exact Core rule contracts.
 *
 * @package Elavira
 */

namespace Elavira\Rules;

/** Plain-language guidance; detection metadata remains in the rule definitions. */
final class CoreRuleGuidance {
	/**
	 * Return explicitly reviewed guidance keyed by rule ID and contract version.
	 *
	 * Historical contracts without an entry retain their original editorial copy.
	 * Literal translation calls keep every new sentence discoverable by WP tools.
	 *
	 * @return array
	 */
	public static function all() {
		$guidance             = array(
			'elavira.image.alt_missing@1.0.0'              => array(
				'title'                 => __( 'Image is missing its alt attribute', 'elavira' ),
				'summary'               => __( 'Elavira found an image without an alt attribute, the place where HTML supplies its text alternative.', 'elavira' ),
				'why_it_matters'        => __( 'Without an alternative or an intentional empty alt attribute, someone who cannot see the image may miss information or hear an unhelpful filename.', 'elavira' ),
				'what_to_check'         => __( 'Locate the image using its filename or the audited page. Decide what it contributes here: information, a link or button action, meaningful words, or decoration. An absent alt attribute is different from alt="", which intentionally provides no alternative text.', 'elavira' ),
				'recommendation'        => __( 'Add an alt attribute. For an informative image, write the information needed in this context. For a purely decorative image, use alt="". If the image supplies a link or button name, communicate its destination or action. Include meaningful words shown in an image; do not replace them with a description of its appearance.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the rendered image to confirm the alt attribute exists. Read the alternative with the surrounding content; for a linked image, check what a screen reader announces for the link. Confirm information or function is preserved, then re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: set alternative text in the Image block or Media Library for this use. Code fix: ask the theme or plugin author to output the attribute if the editor setting is ignored. Library changes may not update existing blocks.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer native img alt. An image inside a link with useful text can have empty alt if it adds no information. Do not leave an image-only link unnamed; inspect the browser accessibility information when ARIA also contributes a name.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<img src="divider.svg">', 'elavira' ),
						'consider'    => __( '<img src="divider.svg" alt="">', 'elavira' ),
						'explanation' => __( 'An empty alternative fits a divider that adds only decoration. It does not fit an image that communicates information or provides the only name of a link.', 'elavira' ),
					),
				),
			),
			'elavira.links.missing_accessible_name@1.0.0'  => array(
				'title'                 => __( 'Link has no detected accessible name', 'elavira' ),
				'summary'               => __( 'Elavira did not find a supported accessible name for this link: text that identifies it to assistive technology.', 'elavira' ),
				'why_it_matters'        => __( 'A person navigating links with a screen reader may hear only a destination address or an unnamed link and cannot confidently choose it.', 'elavira' ),
				'what_to_check'         => __( 'Open the audited page and find the recorded link. Check whether it contains text, an image, or both. Inspect the name announced for the whole link. An image filename helps you locate it; it is not a useful substitute for its purpose.', 'elavira' ),
				'recommendation'        => __( 'Give the link meaningful visible text describing its destination or action. For an image-only link, an appropriate image alt can supply that name: explain what following the link does. If useful text already names the link, a decorative image can keep alt="". Repair broken naming references instead of piling on ARIA.', 'elavira' ),
				'verification_guidance' => __( 'Focus the link and inspect its name with a screen reader or browser accessibility tools. Confirm it describes the actual destination before following it. Check that decorative content is not announced redundantly, then re-audit for the missing name.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit the Navigation/menu item, linked text, or linked Image block. Code fix: correct a template or component that creates an empty link or overrides its name.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer an a element with href and meaningful content. aria-label or aria-labelledby may override content-derived names. Recorded simple name excerpts are not a complete browser accessibility-tree name; check reference relationships on the rendered page.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<a href="/contact/"><img src="envelope.svg" alt=""></a>', 'elavira' ),
						'consider'    => __( '<a href="/contact/"><img src="envelope.svg" alt="Contact us"></a>', 'elavira' ),
						'explanation' => __( 'This name fits only if the link leads to contact information or a contact action. Choose wording for the actual destination.', 'elavira' ),
					),
				),
			),
			'elavira.link.purpose_review@2.0.0'            => array(
				'title'                 => __( 'Link purpose needs a context check', 'elavira' ),
				'summary'               => __( 'Elavira found a link name that may be too vague to explain where the link goes. This is a prompt to check context, not a confirmed failure.', 'elavira' ),
				'why_it_matters'        => __( 'Someone choosing a link needs enough information to predict its destination or action, including when reading with a screen reader.', 'elavira' ),
				'what_to_check'         => __( 'Read the link text and the immediate paragraph excerpt, when recorded. Does that sentence or paragraph explain the destination? Check the full page for relevant context connected to the link in the document structure, such as its enclosing list item or table cell; visual proximity alone is not enough. Generic wording can be acceptable when that context makes the purpose clear.', 'elavira' ),
				'recommendation'        => __( 'If the destination is still unclear, rewrite the link text to name it. For an image-only link, check the image alternative as part of the link name: it should communicate the action or destination, not merely the picture. Include meaningful words visible in a linked image. Keep empty alt for a decorative image when useful text already names the same link.', 'elavira' ),
				'verification_guidance' => __( 'Read the link in its actual surrounding content with a screen reader and confirm the purpose is understandable without activating it. Then compare it with the destination. Re-audit after changes, but make the contextual decision yourself even if the wording still triggers this check.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit the link text in its paragraph, Navigation/menu item, or linked image alternative. Code fix: ask the template author to include each card or article destination in repeated link text when the existing structure supplies no useful context.', 'elavira' ),
				'developer_guidance'    => __( 'Use the recorded link kind, destination, image filename, alt state/excerpt, and visible text when available. Excerpts can be shortened; destination queries and fragments are omitted. A simple available link name is not guaranteed to be the complete accessibility-tree name, especially with aria-labelledby. Inspect the rendered name and relationships when evidence is incomplete.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'Learn more', 'elavira' ),
						'consider'    => __( 'Learn more about our services', 'elavira' ),
						'explanation' => __( 'Use this wording only for a services destination whose purpose is not already clear from associated context.', 'elavira' ),
					),
					array(
						'instead_of'  => __( '<img src="envelope.svg" alt="Envelope icon">', 'elavira' ),
						'consider'    => __( '<img src="envelope.svg" alt="Contact us">', 'elavira' ),
						'explanation' => __( 'Inside an image-only contact link, the second alternative names the destination. Use the actual purpose, not this wording by default.', 'elavira' ),
					),
					array(
						'instead_of'  => __( 'A linked banner saying “View Fall Collection” with alt="Autumn leaves"', 'elavira' ),
						'consider'    => __( 'An alternative that includes “View Fall Collection”', 'elavira' ),
						'explanation' => __( 'The meaningful words and link purpose matter more than the decorative picture. If useful link text already supplies the same purpose, avoid repeating it in a decorative image alternative.', 'elavira' ),
					),
				),
			),
			'elavira.links.identical_name_different_destination@2.0.0' => array(
				'title'                 => __( 'Same link name points to different destinations', 'elavira' ),
				'summary'               => __( 'Elavira found links with the same recorded name that point to different destinations. A person needs to check whether their context distinguishes them.', 'elavira' ),
				'why_it_matters'        => __( 'Repeated names can make it difficult to choose the right page, especially when a screen reader presents several links with the same announcement.', 'elavira' ),
				'what_to_check'         => __( 'Compare each occurrence, its name excerpt, destination and surrounding sentence or paragraph. Can someone distinguish the destinations from information associated with each link? Different addresses alone do not prove different purposes. Open the full page when the captured excerpt or shortened destination is insufficient.', 'elavira' ),
				'recommendation'        => __( 'If different purposes are unclear, give each link text that identifies its particular destination. For image-only links, use alternatives that communicate each destination or action. Keep a repeated name when the purpose is genuinely the same or associated context distinguishes it adequately.', 'elavira' ),
				'verification_guidance' => __( 'Read the links and their associated context with a screen reader, then check the actual destinations. Confirm the distinction makes sense before deciding this is an issue. Re-audit after edits; repeated wording may still need a human decision.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit repeated card, list, or navigation labels and image alternatives. Code fix: update a repeating template to include the corresponding item title in each link where needed.', 'elavira' ),
				'developer_guidance'    => __( 'Do not infer the complete browser name from name fingerprints or excerpts. Check aria-labelledby and other naming sources on the page. Avoid using query-stripped displayed URLs to decide whether full destinations are equivalent.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'Two unrelated article links both called “Read more” without useful context', 'elavira' ),
						'consider'    => __( '“Read our opening-hours update” and “Read our delivery guide”', 'elavira' ),
						'explanation' => __( 'Distinct names help identify these different articles. Repeated names can still work with sufficient associated context.', 'elavira' ),
					),
				),
			),
			'elavira.structure.missing_h1@1.0.0'           => array(
				'title'                 => __( 'Page has no visible H1 heading', 'elavira' ),
				'summary'               => __( 'Elavira found no visible H1 heading. This is a structural warning for human review.', 'elavira' ),
				'why_it_matters'        => __( 'A clear main heading helps readers identify the page topic and helps people navigating by headings orient themselves.', 'elavira' ),
				'what_to_check'         => __( 'Look at the page title and heading outline, including headings supplied by the theme. Is there a clear primary topic, and is that title marked as a heading rather than merely styled as large text? Decide whether the page organization is understandable without relying on visual size.', 'elavira' ),
				'recommendation'        => __( 'Elavira strongly recommends a clear primary document heading. Where the main title is missing or uses ordinary text, make it an appropriate heading and arrange section headings beneath it. Do not add an unrelated title merely to remove the warning. WCAG and HTML do not require exactly one H1.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the public page heading outline and use a screen reader heading list to check whether the main topic and sections are easy to identify. Re-audit for the missing H1, then retain your human assessment of the structure.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: use a Heading block for a title you own. Code fix: adjust the page-title template when the theme supplies it. Check the rendered page before adding a duplicate title.', 'elavira' ),
				'developer_guidance'    => __( 'Use h1 for the primary document heading where appropriate and CSS for visual sizing. Check templates that visually hide or omit titles; an H1 count is not a conformance verdict.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.structure.multiple_h1@1.0.0'          => array(
				'title'                 => __( 'Page has multiple visible H1 headings', 'elavira' ),
				'summary'               => __( 'Elavira found more than one visible H1 heading. Check whether they communicate the page organization clearly.', 'elavira' ),
				'why_it_matters'        => __( 'Several headings presented at the highest level can leave readers unsure which topic is primary or how sections relate.', 'elavira' ),
				'what_to_check'         => __( 'Read the H1 headings and the content each introduces. Are they separate major topics, or have section titles, a logo, or repeated cards been given the same level as the page title? Multiple H1 elements are not automatically a WCAG failure.', 'elavira' ),
				'recommendation'        => __( 'Elavira strongly recommends a clear primary document heading. If other H1 headings introduce subsections, change their levels to reflect those relationships. Keep an intentional structure only after checking it remains understandable. WCAG and HTML do not require exactly one H1.', 'elavira' ),
				'verification_guidance' => __( 'Read the updated heading outline without relying on size or position. Confirm the main topic and subsection relationships are clear, including with screen reader heading navigation. Re-audit, but judge the organization rather than the count alone.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: adjust Heading block levels. Code fix: correct title levels in the theme, repeated cards, or reusable components; the editor outline may not include template headings.', 'elavira' ),
				'developer_guidance'    => __( 'Choose h1–h6 according to content hierarchy and style them with CSS. Avoid globally replacing every H1 without reviewing each template context.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.structure.heading_level_jump@1.0.0'   => array(
				'title'                 => __( 'Heading levels may not match the structure', 'elavira' ),
				'summary'               => __( 'Elavira found a heading that moves down more than one level from the preceding heading. The surrounding structure needs review.', 'elavira' ),
				'why_it_matters'        => __( 'Heading levels tell people which sections belong inside others. A misleading level can suggest a missing section or the wrong relationship.', 'elavira' ),
				'what_to_check'         => __( 'Find the recorded previous and current heading levels in Technical Details. Read their headings and intervening content. Is the second heading a direct subsection, a deeper subsection with a missing parent, or part of a different page region? The sequence alone cannot decide this.', 'elavira' ),
				'recommendation'        => __( 'Change levels when they misrepresent the content hierarchy. Add a parent heading only if a real section needs a title. Returning from a subsection to a higher-level section is normal; do not renumber headings mechanically to create an unbroken sequence.', 'elavira' ),
				'verification_guidance' => __( 'Read the entire affected outline and navigate its headings with a screen reader. Check that the sections and nesting make sense. Re-audit after edits and evaluate any remaining jump in context.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: select the Heading block level that matches the section. Code fix: update repeated components or template headings that impose an unsuitable level. Use typography settings for size.', 'elavira' ),
				'developer_guidance'    => __( 'Use semantic heading elements for structure. Review the surrounding regions before changing h1–h6; adjacent DOM order alone does not establish the intended hierarchy.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'An H2 “Delivery” followed by an H4 “Delivery times” as its direct subsection', 'elavira' ),
						'consider'    => __( 'An H3 “Delivery times” beneath that H2', 'elavira' ),
						'explanation' => __( 'This change fits a direct subsection. Evaluate the actual hierarchy rather than applying it to every level jump.', 'elavira' ),
					),
				),
			),
			'elavira.structure.empty_heading@1.0.0'        => array(
				'title'                 => __( 'Heading has no detected text', 'elavira' ),
				'summary'               => __( 'Elavira found a heading with no accessible text detected by this check.', 'elavira' ),
				'why_it_matters'        => __( 'People navigating by headings may encounter an unexplained stop instead of a useful section title.', 'elavira' ),
				'what_to_check'         => __( 'Locate the heading level recorded in Technical Details. Does it introduce a real section, create blank spacing, or contain content whose name depends on an image or script? Check the rendered heading name before deciding it is empty for users.', 'elavira' ),
				'recommendation'        => __( 'If it introduces a section, supply a concise title that describes that section. If it exists only for spacing, remove the heading markup and use layout or spacing styles. Repair missing image alternatives or delayed heading text when they are the intended title.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the rendered heading and listen to it in a screen reader heading list. Confirm there is a meaningful title or that the unnecessary heading is gone. Re-audit and check nearby heading relationships.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: remove blank Heading blocks or enter their intended titles. Code fix: stop templates from outputting empty headings when a title field is unset.', 'elavira' ),
				'developer_guidance'    => __( 'Do not fill an empty heading with spaces or hidden meaningless text. Check the accessibility-tree name when the heading contains images or referenced content.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.heading.structure_review@2.0.0'       => array(
				'title'                 => __( 'Main content may need headings', 'elavira' ),
				'summary'               => __( 'Elavira found no visible semantic headings on the page or within its main content. Decide whether the content needs section headings.', 'elavira' ),
				'why_it_matters'        => __( 'Headings let readers scan a page and let screen reader users jump between sections. Large or bold text alone may not provide that navigation.', 'elavira' ),
				'what_to_check'         => __( 'Check the recorded issue to see whether it concerns the whole page or its main region. Read that content: does it contain distinct sections or visual titles? A short, simple piece of content may not need multiple sections; a page with clear sections should expose their organization.', 'elavira' ),
				'recommendation'        => __( 'Turn visual section titles into descriptive headings when they represent real structure. Add titles for substantial sections that need them. Keep ordinary emphasis as ordinary text; do not invent sections just to satisfy this check.', 'elavira' ),
				'verification_guidance' => __( 'Compare the public page with its heading outline. Use heading navigation to confirm each real section has a useful title and logical level. Re-audit after changes; a person must still judge whether the structure is suitable.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: use Heading blocks for actual section titles. Code fix: have the theme output semantic headings for titles it renders. Review the public template as well as the editor.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer native h1–h6 elements. Do not add role="heading" to unrelated containers; markup must describe the actual content organization.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.document.language_missing@2.0.0'      => array(
				'title'                 => __( 'Page language is missing', 'elavira' ),
				'summary'               => __( 'Elavira found no usable primary language declaration on the root HTML element.', 'elavira' ),
				'why_it_matters'        => __( 'Screen readers use the page language to choose pronunciation rules. Without it, text may be read with the wrong pronunciation.', 'elavira' ),
				'what_to_check'         => __( 'Open the page source or browser inspector and find the root html element. Check whether lang is absent or empty, as recorded. Determine the actual primary language of this page; Elavira does not choose it from the text.', 'elavira' ),
				'recommendation'        => __( 'Declare the page primary language in the html element using its appropriate language tag. Choose the language actually used, including an appropriate regional variant when needed. Do not put the declaration only on a visible heading or in a metadata field.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the rendered html lang value and confirm it matches the page language. Test pronunciation with a screen reader configured to switch languages when practical, then re-audit for the missing declaration.', 'elavira' ),
				'wordpress_guidance'    => __( 'Check the WordPress Site Language setting if it controls this page. Code fix: the theme should output language_attributes() on html. A multilingual page system may set a different value per page; verify its public output.', 'elavira' ),
				'developer_guidance'    => __( 'Use a valid language tag on html, such as en for English only when that is the actual primary language. Mark passages in another language separately where needed; this rule does not assess every passage.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<html>', 'elavira' ),
						'consider'    => __( '<html lang="en">', 'elavira' ),
						'explanation' => __( 'This example fits an English page. Choose the actual page language; do not copy en for every site.', 'elavira' ),
					),
				),
			),
			'elavira.document.invalid_language@2.0.0'      => array(
				'title'                 => __( 'Page language declaration is invalid', 'elavira' ),
				'summary'               => __( 'Elavira found a page language declaration that fails this check of language-tag syntax or the registered primary language.', 'elavira' ),
				'why_it_matters'        => __( 'A language value that assistive technology cannot interpret may prevent reliable pronunciation of the page.', 'elavira' ),
				'what_to_check'         => __( 'Read the declared language and recorded reason in Technical Details. Compare that value with the actual primary language of the page. A country name, a full language name, or an invented abbreviation is not a substitute for an appropriate language tag.', 'elavira' ),
				'recommendation'        => __( 'Replace the invalid html lang value with a valid tag for the actual primary language. Correct the setting or template that produces it; do not guess from the page content or simply copy a tag from another site.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the root html element after saving and confirm its tag represents the intended language. Check pronunciation with a screen reader when practical, then re-audit. This bounded check does not validate every aspect of every language subtag.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content/configuration fix: check Site Language or the page-language setting if one exists. Code fix: correct template language_attributes() output or the integration overriding it.', 'elavira' ),
				'developer_guidance'    => __( 'Use BCP 47 language tags. Follow the recorded syntax or primary-subtag reason; the bundled registry is a bounded validator, not a language detector.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<html lang="English">', 'elavira' ),
						'consider'    => __( '<html lang="en">', 'elavira' ),
						'explanation' => __( 'For a page whose primary language is English, use the language tag rather than its written-out name.', 'elavira' ),
					),
				),
			),
			'elavira.form.accessible_name_missing@2.0.0'   => array(
				'title'                 => __( 'Form control has no detected accessible name', 'elavira' ),
				'summary'               => __( 'Elavira did not find a supported accessible name for this form control: the name assistive technology uses to identify it.', 'elavira' ),
				'why_it_matters'        => __( 'Someone using a screen reader may reach a field and hear its type without knowing what information to enter or which choice to make.', 'elavira' ),
				'what_to_check'         => __( 'Use the recorded control type and field name, when available, to locate the control. The field name is an internal identifier, not proof of an accessible label. Check what a screen reader announces and how any visible label is connected. This finding does not mean there is definitely no label element.', 'elavira' ),
				'recommendation'        => __( 'Give the control a clear name matching its purpose. For standard inputs, selects and text areas, prefer a visible native label connected to the control. Repair an existing label connection if it is broken. Other valid naming methods can work, but placeholder text alone does not provide a persistent visible label.', 'elavira' ),
				'verification_guidance' => __( 'Focus the control with a screen reader and confirm its name identifies the expected entry or choice. Check that the visible label stays present while typing, and that the name is not an unrelated field name. Re-audit the rendered form.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: enable and edit the field label in the form settings. Code fix: connect label for to the control id or wrap a labelable control in its label. Ask the form or theme author when settings do not affect output.', 'elavira' ),
				'developer_guidance'    => __( 'Accessible names can come from native labels, suitable content or supported ARIA naming. Inspect the resulting name, not just the presence of label markup. Keep IDs unique; prefer native controls and visible labels.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<input id="email" type="email">', 'elavira' ),
						'consider'    => __( '<label for="email">Email address</label><input id="email" type="email">', 'elavira' ),
						'explanation' => __( 'This label identifies an email field and connects to its unique ID. Use wording appropriate to the actual field.', 'elavira' ),
					),
				),
			),
			'elavira.forms.broken_label_reference@1.0.0'   => array(
				'title'                 => __( 'Form label does not connect reliably', 'elavira' ),
				'summary'               => __( 'Elavira found a label whose for attribute does not connect reliably to a labelable control.', 'elavira' ),
				'why_it_matters'        => __( 'A visible label may look correct while assistive technology cannot associate it with the intended field. Selecting the label may also fail to focus or toggle the control.', 'elavira' ),
				'what_to_check'         => __( 'Check the recorded reference state: empty, missing, duplicate, or not labelable. Locate both the label and the intended control. Confirm their for and id values match exactly and the ID occurs once. Another naming source may still name the field, so test the actual result.', 'elavira' ),
				'recommendation'        => __( 'Correct the label connection so for points to the unique id of the intended labelable control. Remove an obsolete label only if it no longer belongs to a field. Do not connect it to a surrounding layout container.', 'elavira' ),
				'verification_guidance' => __( 'Select the visible label and confirm the intended field receives focus or the associated checkbox/radio toggles. Focus the control with a screen reader and check its name, then re-audit for the broken reference.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: check the field-label settings. Code fix: correct generated IDs in the form plugin or template, including repeated forms on the same page.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer label for/id or valid label wrapping for native controls. Renaming an ID requires updating every intended reference, including help and error descriptions.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.forms.placeholder_only_label@1.0.0'   => array(
				'title'                 => __( 'Field may rely on a disappearing placeholder', 'elavira' ),
				'summary'               => __( 'Elavira found a text-entry control whose placeholder appears to be its only supported labeling source.', 'elavira' ),
				'why_it_matters'        => __( 'Placeholder text disappears as someone types. A person reviewing their entries may no longer know what belongs in the field, even if a browser announces the placeholder as its name.', 'elavira' ),
				'what_to_check'         => __( 'Find the input or text area and enter temporary test text in a safe test form. Does a clear label remain visible? Check its screen reader name and whether nearby instructions actually identify this field. A placeholder-derived name alone does not answer those questions.', 'elavira' ),
				'recommendation'        => __( 'If the field lacks a persistent label, add a visible label and associate it with the control. Keep the placeholder only for an optional short example. Move essential format instructions outside the field so they remain available.', 'elavira' ),
				'verification_guidance' => __( 'Check the field when empty, focused and filled. Confirm its label remains visible and its screen reader name is meaningful in each state. Re-audit after the labeling change.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: turn on visible field labels in the form settings and move examples into help text if needed. Code fix: add a connected native label when the component supplies only a placeholder.', 'elavira' ),
				'developer_guidance'    => __( 'Do not replace placeholder-only labeling with aria-label alone if a visible label is needed. Prefer label for/id; associate additional instructions with aria-describedby when appropriate.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<input placeholder="Email address">', 'elavira' ),
						'consider'    => __( '<label for="email">Email address</label><input id="email" type="email">', 'elavira' ),
						'explanation' => __( 'A persistent label remains available after a person enters an address.', 'elavira' ),
					),
				),
			),
			'elavira.forms.required_instruction_review@1.0.0' => array(
				'title'                 => __( 'Required-field instructions need review', 'elavira' ),
				'summary'               => __( 'Elavira found a control marked as required. A person needs to check how that requirement and any entry instructions are communicated.', 'elavira' ),
				'why_it_matters'        => __( 'People can waste time submitting incomplete forms if they cannot tell which fields are required or what format is expected.', 'elavira' ),
				'what_to_check'         => __( 'Before filling the form, identify the recorded control. Is its required status apparent in visible text or an explained symbol, and announced with its name by a screen reader? Are format instructions available before an error occurs? A required attribute by itself does not establish that these instructions are clear.', 'elavira' ),
				'recommendation'        => __( 'If the requirement is unclear, add a visible indication such as “Required” to the label or explain the symbol used. Provide necessary format instructions next to the field. Keep the actual required state consistent with the visible instructions.', 'elavira' ),
				'verification_guidance' => __( 'Read the form before entering anything, then focus the field with a screen reader. Confirm its name, required status and necessary instructions are available. Test an empty submission in a safe test environment; re-audit, retaining human judgment about clarity.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit field labels and help text in the form settings. Code fix: connect instructions to the field and correct required-state output when the form component does not expose it.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer native required on supporting form controls. aria-required communicates a state but does not perform validation. Use aria-describedby for relevant help; do not hide essential instructions in a placeholder.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.forms.error_identification_review@1.0.0' => array(
				'title'                 => __( 'Form errors need an interaction check', 'elavira' ),
				'summary'               => __( 'Elavira found an invalid-state or announcement pattern in this form. That pattern alone does not show whether errors are explained well.', 'elavira' ),
				'why_it_matters'        => __( 'Someone who cannot identify the field with an error or understand how to correct it may be unable to finish the form.', 'elavira' ),
				'what_to_check'         => __( 'In a safe test environment, submit missing or invalid sample entries. Does the message identify the affected field, explain the problem in text, and suggest a correction when known and appropriate? Can keyboard and screen reader users find the message and return to the field? An announcement region may have another purpose, so check what actually happens.', 'elavira' ),
				'recommendation'        => __( 'If errors are unclear, write specific messages next to the affected fields and connect them to those fields. Provide a usable route from any error summary to each field. Preserve valid entries and make error updates discoverable without sending focus somewhere unexpected.', 'elavira' ),
				'verification_guidance' => __( 'Repeat the invalid submission using only the keyboard and a screen reader. Confirm the error and useful correction are announced or discoverable, correct the entry, and check that the stale error clears. Re-audit the error state; automation cannot verify the entire interaction.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: improve validation-message wording in the form settings. Code fix: ask the form author to associate errors, manage announcements and support keyboard navigation to affected fields.', 'elavira' ),
				'developer_guidance'    => __( 'Synchronize aria-invalid with actual validation, and reference relevant error text through supported description/error relationships. Use live announcements deliberately; their presence alone is not proof users receive useful feedback.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'Invalid input', 'elavira' ),
						'consider'    => __( 'Enter a date in day/month/year format, for example 24/09/2026.', 'elavira' ),
						'explanation' => __( 'This message helps only if that format is actually accepted. Identify the field as well when the message is in an error summary.', 'elavira' ),
					),
				),
			),
			'elavira.semantics.control_missing_name@1.0.0' => array(
				'title'                 => __( 'Control has no detected accessible name', 'elavira' ),
				'summary'               => __( 'Elavira did not find a supported accessible name for a component marked as an interactive control.', 'elavira' ),
				'why_it_matters'        => __( 'A screen reader may announce a button, switch or other control without saying what it does. Voice-control users may also struggle to identify it.', 'elavira' ),
				'what_to_check'         => __( 'Find the recorded role in Technical Details; a role tells assistive technology what kind of component this is. Check its visible purpose and the name announced for the whole control. For icon controls, determine the action rather than simply naming the icon.', 'elavira' ),
				'recommendation'        => __( 'Give the control a clear name describing its action or setting, preferably through visible text. Use a native button or input where it fits. For an icon-only button, provide an appropriate accessible name and ensure the purpose is also understandable visually.', 'elavira' ),
				'verification_guidance' => __( 'Focus and operate the control with a screen reader. Confirm the name identifies the action, agrees with any visible label, and remains useful when the state changes. Re-audit for the missing name.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit the control label if the block exposes it. Code fix: correct the custom component or template that creates the unnamed control.', 'elavira' ),
				'developer_guidance'    => __( 'Check browser accessibility information for the final name. aria-label and aria-labelledby can override content; fix the intended naming source instead of adding conflicting names.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<button><svg aria-hidden="true"></svg></button>', 'elavira' ),
						'consider'    => __( '<button aria-label="Search"><svg aria-hidden="true"></svg></button>', 'elavira' ),
						'explanation' => __( 'An accessible name fits this icon button only if its action is Search. A visible text label is preferable when practical.', 'elavira' ),
					),
				),
			),
			'elavira.semantics.invalid_role@1.0.0'         => array(
				'title'                 => __( 'Control role is not recognized', 'elavira' ),
				'summary'               => __( 'Elavira found an explicit role with no usable role token in its bundled vocabulary. Check what kind of component users actually receive.', 'elavira' ),
				'why_it_matters'        => __( 'Assistive technology may announce the wrong kind of control or lose information needed to operate it. Native HTML may still provide a suitable role.', 'elavira' ),
				'what_to_check'         => __( 'Read the invalid token and native-role state in Technical Details. Ask what this component does, then inspect the role exposed by the browser. If native HTML already supplies the correct role and behavior, the extra role may be unnecessary; invalid syntax alone is not a confirmed accessibility failure.', 'elavira' ),
				'recommendation'        => __( 'Remove the unnecessary role if native HTML already expresses the intended component. Otherwise use an appropriate native element, or implement the correct supported ARIA role together with all required states and keyboard behavior. Do not choose a role merely to remove the finding.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the resulting role and name, then operate the component with a keyboard and screen reader. Confirm the announced type matches its behavior and re-audit for the invalid token.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the component or template emitting the role. A content editor may not expose this setting; give the responsible developer the recorded token and location.', 'elavira' ),
				'developer_guidance'    => __( 'ARIA describes semantics; it does not create keyboard interaction. The check uses its bundled WAI-ARIA vocabulary, so investigate newer or unusual markup before treating the warning as a proven user impact.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.semantics.required_state_missing@1.0.0' => array(
				'title'                 => __( 'Control is missing a required state or value', 'elavira' ),
				'summary'               => __( 'Elavira found a missing or invalid state/property required by this control role.', 'elavira' ),
				'why_it_matters'        => __( 'A person using assistive technology may be unable to tell whether a control is checked, expanded, or set to a particular value.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded role, required attribute and missing/invalid reason. Determine the actual state or value of this control. Do not assume a default value is correct just because it removes the warning.', 'elavira' ),
				'recommendation'        => __( 'Prefer a native control that exposes the needed state automatically. If a custom control is necessary, supply a valid value for the required property and update it whenever the control changes. Match the visible and functional state.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the state reported by the browser and listen to the control with a screen reader before and after changing it. Confirm the value tracks the actual behavior, then re-audit for the required property.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the state handling in the theme or plugin component. Changing nearby text alone will not repair a missing programmatic state.', 'elavira' ),
				'developer_guidance'    => __( 'Use the exact recorded role/attribute pair to locate the relevant implementation. Native checkbox checked state is preferable to manually synchronizing a custom role="checkbox" and aria-checked.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.semantics.state_consistency_review@1.0.0' => array(
				'guided_decision'       => 'aria_behavior',
				'title'                 => __( 'Control state needs an interaction check', 'elavira' ),
				'summary'               => __( 'Elavira found a control that exposes a changeable ARIA state or value. A person must check whether it stays accurate during use.', 'elavira' ),
				'why_it_matters'        => __( 'A control that announces “collapsed” when its content is open, or an outdated value, gives assistive technology users conflicting information.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded state attribute and role. Operate the component through its available states and compare what is visible, what the control does, and what a screen reader announces. A valid attribute value is acceptable only when it reflects the actual state.', 'elavira' ),
				'recommendation'        => __( 'If those disagree, update the component so its exposed state changes with its visible and functional state. Prefer native controls where possible. Do not hard-code a value that is correct only at page load.', 'elavira' ),
				'verification_guidance' => __( 'Repeat the relevant interaction in both directions: open/close, select/unselect, check/uncheck, or change the value. Confirm screen reader announcements follow every change. Re-audit the states, but use interaction testing to decide correctness.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the theme or plugin event/state logic; this usually cannot be fixed by editing the label in a page block.', 'elavira' ),
				'developer_guidance'    => __( 'Synchronize the recorded aria-checked, aria-expanded, aria-pressed, aria-selected or aria-valuenow with the underlying state. Test programmatic updates as well as pointer and keyboard changes.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'A disclosure announces aria-expanded="false" while its panel is open', 'elavira' ),
						'consider'    => __( 'Update aria-expanded to "true" while open and "false" while closed', 'elavira' ),
						'explanation' => __( 'The attribute must reflect the panel state throughout interaction; adding it once is insufficient.', 'elavira' ),
					),
				),
			),
			'elavira.semantics.native_semantics_overridden@1.0.0' => array(
				'guided_decision'       => 'aria_behavior',
				'title'                 => __( 'Control role may not match its HTML behavior', 'elavira' ),
				'summary'               => __( 'Elavira found an HTML control whose explicit ARIA role differs from its native role. Check whether that change matches its behavior.', 'elavira' ),
				'why_it_matters'        => __( 'A control that behaves like one thing but is announced as another can give keyboard and screen reader users the wrong expectations.', 'elavira' ),
				'what_to_check'         => __( 'Compare the recorded native and explicit roles. Does the control navigate, submit, toggle or select? Test whether the browser-announced role and expected keys match that action. A deliberate role change needs a complete implementation; the difference alone does not prove failure.', 'elavira' ),
				'recommendation'        => __( 'Use the native element that fits the action, such as an anchor for navigation or a button for an action. Remove an unnecessary conflicting role. If a custom pattern is genuinely needed, implement its full naming, state and keyboard behavior.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the exposed role, then test the action with its expected keys and a screen reader. Confirm the role describes the interaction accurately, and re-audit the markup.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: change the element or role in the theme or plugin component. Styling can preserve the visual design without mislabeling the control type.', 'elavira' ),
				'developer_guidance'    => __( 'Changing role does not change native event behavior. Avoid using ARIA to disguise a mismatched element when native HTML supports the intended interaction.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.aria.invalid_attribute@1.0.0'         => array(
				'title'                 => __( 'ARIA attribute name is not recognized', 'elavira' ),
				'summary'               => __( 'Elavira found an aria-* attribute name it does not recognize in its bundled vocabulary. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'The browser may ignore a misspelled instruction intended to supply a name, relationship or state. The user impact depends on what information is otherwise available.', 'elavira' ),
				'what_to_check'         => __( 'Read the attribute name in Technical Details and determine what its author intended. Is it a typo, an unnecessary attribute, or vocabulary this check does not support? Inspect the actual name, role and state before concluding that a user is affected.', 'elavira' ),
				'recommendation'        => __( 'Correct a misspelling only when the intended attribute is appropriate for this element. Remove unused ARIA instead of adding more attributes to quiet the warning. Prefer a native label or control when it supplies the intended behavior.', 'elavira' ),
				'verification_guidance' => __( 'Inspect browser accessibility information to confirm the intended name, relationship or state is now available. Exercise any related interaction with a screen reader, then re-audit for the unknown attribute.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: locate the attribute in the template, custom HTML block or plugin output. Share its exact recorded spelling with the maintainer.', 'elavira' ),
				'developer_guidance'    => __( 'An aria-* prefix does not make an arbitrary attribute meaningful. Check supported ARIA vocabulary and role applicability; unknown syntax alone is not a mapped WCAG failure.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.aria.invalid_value@1.0.0'             => array(
				'title'                 => __( 'ARIA attribute value needs correction', 'elavira' ),
				'summary'               => __( 'Elavira found an ARIA attribute value that does not have the expected form. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'An ignored or misinterpreted value can hide a control state or break information that assistive technology needs.', 'elavira' ),
				'what_to_check'         => __( 'Read the attribute name and value reason in Technical Details. Inspect the full rendered value on the page and determine what state or relationship was intended. Check what the browser actually exposes; this warning alone does not establish the accessibility consequence.', 'elavira' ),
				'recommendation'        => __( 'Use a valid value for that specific attribute that reflects the actual component state or target. Remove unnecessary ARIA when native HTML supplies the information. Do not replace every invalid value with true or false; different attributes accept different kinds of values.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the corrected value in the browser accessibility information, then change the relevant control state and check it updates correctly. Test with a screen reader and re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the component property, template binding or custom HTML that outputs the value. Verify the rendered output after the change.', 'elavira' ),
				'developer_guidance'    => __( 'Boolean, tristate, numeric and ID-reference attributes have different value rules. Validate the recorded attribute specifically and synchronize dynamic values with behavior.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'aria-expanded="yes"', 'elavira' ),
						'consider'    => __( 'aria-expanded="true"', 'elavira' ),
						'explanation' => __( 'Use true only when the controlled content is expanded; use false when collapsed and update the value as it changes.', 'elavira' ),
					),
				),
			),
			'elavira.aria.prohibited_attribute@1.0.0'      => array(
				'guided_decision'       => 'aria_behavior',
				'title'                 => __( 'Role does not allow this naming attribute', 'elavira' ),
				'summary'               => __( 'Elavira found a naming attribute on a role that does not allow that form of naming. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'The intended name may be ignored, leaving users without the information the author expected to provide.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded role and attribute. Is the text meant to name a control, label a region, or simply appear as content? Inspect the role actually exposed by the browser and whether that component needs a name. This syntax warning is not by itself a confirmed WCAG failure.', 'elavira' ),
				'recommendation'        => __( 'Remove an unnecessary naming attribute from a role that cannot use it. Put meaningful text in the document, or choose a suitable native element for the intended control or region. Change the role only if the component genuinely has that purpose and behavior.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the resulting role and name or content with browser accessibility tools and a screen reader. Confirm the intended information is available in the right place, then re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the template or plugin markup assigning the role and naming attribute. Adding another label setting may not fix a prohibited combination.', 'elavira' ),
				'developer_guidance'    => __( 'Check aria-label/aria-labelledby applicability for the actual role. Do not turn a generic container into an interactive role just to make a name appear.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.aria.required_attribute_missing@1.0.0' => array(
				'title'                 => __( 'Role is missing a required attribute', 'elavira' ),
				'summary'               => __( 'Elavira found a role without an attribute that its defined pattern requires. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'Required properties help assistive technology describe how a component works or what state it is in. Missing them may make the component confusing.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded role and missing attribute. Check whether that role fits the actual component and whether the intended information is available to assistive technology. This markup review is distinct from a rule that establishes a missing semantic state.', 'elavira' ),
				'recommendation'        => __( 'Prefer native HTML that provides the required information. If this custom role is necessary, implement the missing attribute with an accurate value and the behavior that maintains it. Remove an inappropriate role rather than supplying meaningless values.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the property in browser accessibility information and test the relevant interaction with a screen reader. Confirm it describes the real state throughout use, then re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: have the component author correct the role implementation and state handling. Include the exact role and attribute from Technical Details.', 'elavira' ),
				'developer_guidance'    => __( 'Follow the requirements for the specific role; do not add a generic collection of ARIA attributes. Overlapping semantic-state findings may supersede this lower-level syntax warning.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.aria.broken_id_reference@1.0.0'       => array(
				'title'                 => __( 'ARIA reference does not resolve reliably', 'elavira' ),
				'summary'               => __( 'Elavira found an ARIA reference that does not resolve cleanly to the intended content or element. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'A broken reference can leave a control unnamed, disconnect help text, or point assistive technology to the wrong part of a component.', 'elavira' ),
				'what_to_check'         => __( 'Read the attribute and reference state: missing, duplicate, empty, or no usable text. Find its referenced IDs on the rendered page. Determine what each should supply and inspect the actual name or relationship. Simple text inspection may not capture complex referenced content.', 'elavira' ),
				'recommendation'        => __( 'Repair each reference so it points to the intended uniquely identified element. Supply useful text when the reference is meant to name or describe something. Remove an obsolete reference only after confirming the intended information remains available.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the resolved name, description or relationship with browser accessibility tools. Focus and use the component with a screen reader, including states that insert referenced content, then re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: update IDs and references together in the component or template. Repeated blocks and dynamically inserted forms need unique IDs across the public page.', 'elavira' ),
				'developer_guidance'    => __( 'aria-labelledby supplies a name; aria-describedby supplies a description; other ID-reference attributes define other relationships. Fix the actual attribute rather than substituting one kind of relationship for another.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.aria.hidden_focusable_content@1.0.0'  => array(
				'title'                 => __( 'Hidden content may still receive keyboard focus', 'elavira' ),
				'summary'               => __( 'Elavira found a potentially focusable control inside content marked aria-hidden="true". ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'Keyboard focus may reach something that a screen reader cannot identify because its surrounding content is hidden from assistive technology.', 'elavira' ),
				'what_to_check'         => __( 'Locate the recorded descendant and its aria-hidden ancestor. Test whether Tab, Shift+Tab or script moves focus into it. If this content is meant to be unavailable, it should not receive focus; if it is usable, it needs to be exposed. DOM inspection alone does not establish the actual focus behavior.', 'elavira' ),
				'recommendation'        => __( 'Remove aria-hidden from usable content and its relevant ancestors. If the region is intentionally inactive, make its controls unavailable to focus and interaction using an appropriate hidden or inert state. Move focus to a logical available control before hiding an active region.', 'elavira' ),
				'verification_guidance' => __( 'Navigate through the area in both directions with the keyboard and a screen reader. Trigger any show/hide state. Confirm focus never lands on unavailable content and each usable control is announced, then re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct visibility and focus management in the modal, menu or other component that owns this region. A descendant aria-hidden="false" does not undo a hidden ancestor.', 'elavira' ),
				'developer_guidance'    => __( 'aria-hidden removes content from the accessibility tree; it does not prevent keyboard focus. Coordinate hidden/inert state and focus restoration with the component lifecycle.', 'elavira' ),
				'examples'              => array(),
				'learn_topic'           => 'keyboard_accessibility',
			),
			'elavira.aria.duplicate_id_reference@1.0.0'    => array(
				'title'                 => __( 'Label or ARIA reference uses a duplicated ID', 'elavira' ),
				'summary'               => __( 'Elavira found a labeling or ARIA relationship that refers to an ID used by more than one element. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'The browser may connect a field or component to the wrong label, description or target, even though everything looks right visually.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded attribute and duplicate count. Locate the repeated ID values on the public page and identify which element the relationship should target. Inspect the resulting name or relationship before deciding the user impact.', 'elavira' ),
				'recommendation'        => __( 'Assign unique IDs to the repeated elements and update each reference to its intended target. Check repeated forms, cards and hidden copies too. Do not change IDs without updating labels, descriptions and script references that rely on them.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the resolved label or relationship for each repeated component, not just the first one. Test them with a screen reader and re-audit to confirm the ambiguity is gone.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct ID generation in the repeating block, template or plugin. Multiple instances on one page must not reuse fixed IDs.', 'elavira' ),
				'developer_guidance'    => __( 'An ID is a document-wide identifier. The issue here is a referenced ambiguity, not a blanket claim that any duplicated ID alone is a WCAG failure.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.aria.redundant_role@1.0.0'            => array(
				'title'                 => __( 'Explicit role repeats the native HTML role', 'elavira' ),
				'summary'               => __( 'Elavira found an explicit role that repeats the role already supplied by the HTML element. This is a best-practice warning, not a mapped WCAG failure. ARIA adds information about names, relationships or states for assistive technology; it does not create interaction behavior.', 'elavira' ),
				'why_it_matters'        => __( 'Redundant markup often adds no benefit and can make a component harder to maintain. An intentional compatibility reason may justify keeping it.', 'elavira' ),
				'what_to_check'         => __( 'Compare the recorded native and explicit roles. Does native HTML already expose the intended role? Check whether the extra role supports a documented browser or assistive-technology compatibility need before removing it.', 'elavira' ),
				'recommendation'        => __( 'If it serves no necessary purpose, remove the repeated role and retain the native element. If there is a tested compatibility reason to keep it, record that decision. Do not replace the native element with a generic container just to avoid duplication.', 'elavira' ),
				'verification_guidance' => __( 'Inspect the role after removal and confirm keyboard and screen reader behavior are preserved. Re-audit if you change it. Keeping an intentionally redundant role does not by itself establish an accessibility issue.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: simplify the component template only after checking why the role was added. Content editors usually do not control this markup.', 'elavira' ),
				'developer_guidance'    => __( 'Native semantics are usually preferable to repeated ARIA. Test the supported browser and assistive-technology combinations when compatibility motivated the role.', 'elavira' ),
				'examples'              => array(
					array(
						// phpcs:ignore WordPress.WP.I18n.NoHtmlWrappedStrings -- Literal escaped code example, not rendered HTML.
						'instead_of'  => __( '<button role="button">Save</button>', 'elavira' ),
						// phpcs:ignore WordPress.WP.I18n.NoHtmlWrappedStrings -- Literal escaped code example, not rendered HTML.
						'consider'    => __( '<button>Save</button>', 'elavira' ),
						'explanation' => __( 'The native button already supplies the button role. Retain additional markup only for a justified, tested reason.', 'elavira' ),
					),
				),
			),
			'elavira.keyboard.positive_tabindex@1.0.0'     => array(
				'title'                 => __( 'Positive tabindex may disrupt keyboard order', 'elavira' ),
				'summary'               => __( 'Elavira found a positive tabindex value, which can move a control ahead of the normal keyboard sequence.', 'elavira' ),
				'why_it_matters'        => __( 'Unexpected jumps can make keyboard users lose their place or reach controls in an order that does not match the task.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded tabindex value and locate the control. Starting before the affected area, use Tab and Shift+Tab. Does focus move through the content in a meaningful order, or jump away and return later? A positive value signals risk, not a confirmed failure.', 'elavira' ),
				'recommendation'        => __( 'If the order is confusing, arrange the HTML in a logical sequence and remove positive tabindex values. Use native controls in their normal sequence; use tabindex="0" only when a custom element needs an ordinary tab stop. Do not assign more positive values to patch the sequence.', 'elavira' ),
				'verification_guidance' => __( 'Tab forward and backward through the whole affected task, including newly opened content. Confirm every needed control is reachable in a meaningful order and the focus position remains clear. Re-audit and retain the interaction-based decision.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: ask the template or component author to remove artificial ordering and correct source order. Visual layout settings alone may not change keyboard order.', 'elavira' ),
				'developer_guidance'    => __( 'Positive tabindex entries precede normal tab stops. Preserve intentional composite-widget navigation; tabindex="-1" can support managed focus without a sequential tab stop.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.keyboard.non_native_interactive@1.0.0' => array(
				'title'                 => __( 'Custom control needs a keyboard check', 'elavira' ),
				'summary'               => __( 'Elavira found an element presented as an interactive control without the usual native HTML control behavior.', 'elavira' ),
				'why_it_matters'        => __( 'A custom control can look clickable while being unreachable or unusable with a keyboard.', 'elavira' ),
				'what_to_check'         => __( 'Read the recorded role and find the control. Test the keys appropriate to that role: Enter for a link; Enter and Space for a button; Space for a checkbox. Check how it receives focus and whether the same action is available without a pointer. More complex widgets need their own interaction pattern.', 'elavira' ),
				'recommendation'        => __( 'Use a native anchor, button or input when it fits the action. If a custom widget is necessary, implement its expected keyboard operation, focus behavior, name and state together. Adding tabindex or a role alone does not make it operable.', 'elavira' ),
				'verification_guidance' => __( 'Reach the control using its intended keyboard route and carry out its action without clicking. Confirm the expected role, name and changing state with a screen reader. Re-audit, but decide operability from interaction testing.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: replace a clickable container with the appropriate native control or correct the custom component implementation. A block label change cannot add missing keyboard behavior.', 'elavira' ),
				'developer_guidance'    => __( 'Match the keyboard pattern to the actual role. Avoid duplicate activation from overlapping key and click handlers; native controls already implement many expected behaviors.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.keyboard.possible_unreachable_control@1.0.0' => array(
				'title'                 => __( 'Custom control may be unreachable by keyboard', 'elavira' ),
				'summary'               => __( 'Elavira found a custom control with no ordinary tab stop or with a negative tabindex. Check how keyboard users reach it.', 'elavira' ),
				'why_it_matters'        => __( 'An action may be unavailable if keyboard users cannot move focus to its control.', 'elavira' ),
				'what_to_check'         => __( 'Try to reach the control from nearby content. For a composite widget such as a tab list or menu, Tab may enter the widget once and arrow keys may reach its items. A negative tabindex can be correct when the widget manages focus; it is a problem if no usable keyboard route reaches a needed action.', 'elavira' ),
				'recommendation'        => __( 'Provide a keyboard route to every required action. Use native controls and normal tab stops where suitable. For a composite widget, repair its entry point and internal arrow-key/focus handling instead of adding every item to the Tab sequence.', 'elavira' ),
				'verification_guidance' => __( 'Test entry, internal movement, activation and exit without a pointer. Check the focused item is visible and announced by a screen reader. Re-audit after changes; the absence of an individual tab stop may still be intentional.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the custom widget focus handling in the theme or plugin. Give its author the recorded role and no-tab-stop or negative-tabindex evidence.', 'elavira' ),
				'developer_guidance'    => __( 'Use roving tabindex or aria-activedescendant only with the complete corresponding interaction pattern. tabindex="-1" is not inherently an accessibility error.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.keyboard.possible_trap@1.0.0'         => array(
				'title'                 => __( 'Application region needs a keyboard-exit check', 'elavira' ),
				'summary'               => __( 'Elavira found an application region with several focusable descendants. A person must test whether focus can leave it.', 'elavira' ),
				'why_it_matters'        => __( 'Someone using only a keyboard can become stuck if a component captures focus without a usable exit.', 'elavira' ),
				'what_to_check'         => __( 'Enter the region by keyboard, try its controls, then use Tab and Shift+Tab to leave. If it uses a special exit command, check that users are told how to use it. An application region is only a risk pattern; this check has not demonstrated a trap.', 'elavira' ),
				'recommendation'        => __( 'If focus cannot leave, remove unnecessary focus capture or provide a reliable keyboard exit and clear instructions when nonstandard keys are needed. Use role="application" only when the interaction genuinely requires it; removing a role alone does not repair trapping script.', 'elavira' ),
				'verification_guidance' => __( 'Test entering, using and leaving the region in both directions with keyboard and screen reader, including after changing its state. Confirm there is always an available exit. Re-audit, but make the trap determination through use.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct focus loops and key handlers in the component. Share the region location and the exact steps that prevent exit with its author.', 'elavira' ),
				'developer_guidance'    => __( 'Do not prevent Tab or other navigation keys without a complete interaction design. Intentional containment in an open modal must still permit keyboard dismissal; this rule specifically records an application-region pattern.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.keyboard.custom_widget_review@1.0.0'  => array(
				'title'                 => __( 'Custom widget needs role-specific keyboard testing', 'elavira' ),
				'summary'               => __( 'Elavira found a custom widget whose keyboard behavior cannot be established from its markup.', 'elavira' ),
				'why_it_matters'        => __( 'People rely on predictable keys to move through options and operate widgets. A role label alone does not supply that behavior.', 'elavira' ),
				'what_to_check'         => __( 'Identify the recorded role and whether it is a composite or specialized widget. For a tab list, test arrow-key movement and tab activation; for a slider, test arrow-key value changes; for a menu, test entry, item movement and Escape to close. Use the pattern appropriate to this widget, not every key on every control.', 'elavira' ),
				'recommendation'        => __( 'Prefer a native control where it meets the need. Otherwise implement the role-specific keyboard pattern, including entry, movement, activation, exit and state updates. Provide clear instructions when the interaction is unusual.', 'elavira' ),
				'verification_guidance' => __( 'Complete the widget task using only the keyboard, then repeat with a screen reader. Confirm focus and selection are distinguishable, state announcements stay accurate, and the user can exit. Re-audit without treating markup as proof of operation.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: have the component author implement and test its full interaction pattern. Visual widget settings alone rarely address missing key handling.', 'elavira' ),
				'developer_guidance'    => __( 'Follow the relevant WAI-ARIA Authoring Practices pattern for the actual role. Composite widgets commonly use one Tab entry point with internal arrow-key movement; activation behavior depends on the pattern.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.focus.possible_hidden_focus@1.0.0'    => array(
				'guided_decision'       => 'focus_visibility',
				'title'                 => __( 'Keyboard focus may not be visible', 'elavira' ),
				'summary'               => __( 'Elavira found author styles that remove an outline without a detectable alternative focus treatment in that rule.', 'elavira' ),
				'why_it_matters'        => __( 'Keyboard users may be unable to see which control will respond to their next action.', 'elavira' ),
				'what_to_check'         => __( 'Use the keyboard to focus the recorded control. Can you clearly see its focus indicator against the surrounding background, including after scrolling or opening content? Another style or script may provide a valid indicator; the recorded CSS pattern alone does not establish failure.', 'elavira' ),
				'recommendation'        => __( 'If focus is hard to see, restore the browser outline or add a clear focus-visible outline, border or other visible treatment. Choose colors and spacing that stand out against adjacent content, and make sure containers do not clip the indicator.', 'elavira' ),
				'verification_guidance' => __( 'Tab and Shift+Tab through the affected controls at different page positions and zoom levels. Confirm a visible indicator follows focus in each relevant state. Re-audit; visually inspect even when this CSS warning remains.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code/theme fix: adjust focus styles in the responsible theme or component stylesheet. Check both light and dark areas if the same control appears in different contexts.', 'elavira' ),
				'developer_guidance'    => __( 'Do not use outline:none without an effective replacement. Test actual :focus/:focus-visible rendering, clipping and backgrounds rather than judging one CSS declaration.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'button:focus { outline: none; }', 'elavira' ),
						'consider'    => __( 'Retain the browser focus outline, or design a clearly visible replacement.', 'elavira' ),
						'explanation' => __( 'The replacement must work against the actual backgrounds and stay visible throughout keyboard navigation.', 'elavira' ),
					),
				),
			),
			'elavira.focus.order_review@1.0.0'             => array(
				'title'                 => __( 'Focus order needs an interaction check', 'elavira' ),
				'summary'               => __( 'Elavira found a focus-order configuration that needs testing. The recorded trigger is a positive tabindex.', 'elavira' ),
				'why_it_matters'        => __( 'If focus reaches content in an illogical order, keyboard and screen reader users may misunderstand relationships or miss a step in a task.', 'elavira' ),
				'what_to_check'         => __( 'Start before the affected region and use Tab and Shift+Tab while following the task. Does the sequence preserve meaning and operation, including when content opens or changes? It need not copy every visual position exactly, but it should not force confusing jumps.', 'elavira' ),
				'recommendation'        => __( 'Correct source order or focus management when the sequence is confusing. Remove unnecessary positive tabindex values. When a control opens new content, place and restore focus according to that interaction rather than sending it to an unrelated part of the page.', 'elavira' ),
				'verification_guidance' => __( 'Complete the task in both keyboard directions and repeat after opening or closing dynamic content. Confirm the sequence remains meaningful and focus is always visible. Re-audit and document the human decision.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct template source order and component focus movement. Check the public layout; rearranging blocks visually may leave their keyboard order unchanged.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer logical DOM order and native focus behavior. Test managed focus as well as sequential navigation; static tabindex evidence cannot prove the resulting experience.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.focus.obscured_review@1.0.0'          => array(
				'guided_decision'       => 'focus_visibility',
				'title'                 => __( 'Overlay may hide a focused control', 'elavira' ),
				'summary'               => __( 'Elavira found a fixed or sticky region near a viewport edge that may cover focused controls.', 'elavira' ),
				'why_it_matters'        => __( 'A keyboard user may lose track of a control when a banner, sticky header or other overlay hides it.', 'elavira' ),
				'what_to_check'         => __( 'Tab and Shift+Tab near the recorded top or bottom boundary, letting the page scroll. Repeat with overlays open and at zoomed or narrow layouts. Does page-authored content completely hide a focused control? Partial covering can still hinder use, but this warning is not a confirmed failure.', 'elavira' ),
				'recommendation'        => __( 'If an overlay hides focus, reduce its footprint, adjust layout or scrolling offsets, or allow it to be dismissed using the keyboard. Aim to keep the whole focused control and its indicator visible.', 'elavira' ),
				'verification_guidance' => __( 'Repeat keyboard navigation around every overlay boundary at the affected viewport sizes and zoom levels. Confirm page-authored content never entirely hides the focused component. Re-audit; determine overlap by observing the actual interaction.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code/theme fix: adjust sticky header, banner or overlay layout and scrolling behavior. A content change may help only if the overlay size is configurable.', 'elavira' ),
				'developer_guidance'    => __( 'WCAG 2.4.11 at AA concerns focus not being entirely hidden by author-created content. Full visibility is a useful stronger goal. Test scroll padding/margins and focus movement in the real layout.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.focus.modal_management_review@1.0.0'  => array(
				'title'                 => __( 'Dialog focus needs an interaction check', 'elavira' ),
				'summary'               => __( 'Elavira found an open dialog that needs a keyboard and screen reader interaction check.', 'elavira' ),
				'why_it_matters'        => __( 'Without suitable focus handling, a person may remain behind the dialog, lose their place, or be unable to close it.', 'elavira' ),
				'what_to_check'         => __( 'Open the dialog with its keyboard trigger. Does focus move to a sensible place inside and is the dialog name announced? Use Tab and Shift+Tab to traverse it; check that background content is unavailable while it is modal. Close it using its keyboard-accessible dismissal control, and test Escape where the dialog pattern supports it.', 'elavira' ),
				'recommendation'        => __( 'Give the dialog a useful name, place focus inside when it opens, and keep modal interaction inside until dismissal. Provide a keyboard-accessible close or completion action. After closing, return focus to the opener or another logical place if the opener no longer exists.', 'elavira' ),
				'verification_guidance' => __( 'Repeat opening, all relevant actions and closing with a keyboard and screen reader. Confirm there is no unreachable content or dead end, background controls stay unavailable, and focus returns logically. Re-audit the open state, retaining human verification.', 'elavira' ),
				'wordpress_guidance'    => __( 'Code fix: correct the dialog component, popup or theme integration. Editing its visible title will not by itself repair focus containment or restoration.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer a native dialog opened modally when appropriate. aria-modal alone does not enforce modality; coordinate background availability, labeling and focus lifecycle.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.contrast.text_insufficient@1.0.0'     => array(
				'title'                 => __( 'Text contrast is too low', 'elavira' ),
				'summary'               => __( 'Elavira measured ordinary-sized text below the contrast threshold for the recorded rendered state.', 'elavira' ),
				'why_it_matters'        => __( 'Text that is too similar in brightness to its background can be difficult to read, particularly for people with low vision.', 'elavira' ),
				'what_to_check'         => __( 'Locate the text and compare the recorded foreground, background and ratio in Technical Details with the public page. The required ratio is 4.5:1, a measure of brightness difference rather than a percentage. Check that you are inspecting the same text and state. If no text excerpt is available, use the element selector in the occurrence Technical Details to find the text, or give that selector and the audited URL to your developer.', 'elavira' ),
				'recommendation'        => __( 'Choose a darker text color on a light background, a lighter text color on a dark background, or change the background so the pair reaches at least 4.5:1. Test candidate colors before applying them. Do not rely on a slight visual adjustment or color hue alone.', 'elavira' ),
				'verification_guidance' => __( 'Measure the effective text/background pair with a contrast tool and confirm at least 4.5:1. Check affected hover, focus and other relevant states separately, then re-audit the rendered page.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content/style fix: change block text/background colors or Global Styles if they control this text. Code fix: adjust the theme or plugin styles when they override those settings.', 'elavira' ),
				'developer_guidance'    => __( 'Use WCAG relative luminance for effective rendered colors. The recorded ratio concerns only the evaluated state; source CSS values may differ because of transparency or layering.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.contrast.large_text_insufficient@1.0.0' => array(
				'title'                 => __( 'Large-text contrast is too low', 'elavira' ),
				'summary'               => __( 'Elavira measured large text below the contrast threshold for the recorded rendered state.', 'elavira' ),
				'why_it_matters'        => __( 'Large lettering can still be difficult to read when its brightness is too close to the background.', 'elavira' ),
				'what_to_check'         => __( 'Find the text and inspect its recorded font size, weight, colors and ratio. The applicable threshold here is 3:1. Confirm the text still qualifies as large in the layout being tested; smaller text generally needs 4.5:1.', 'elavira' ),
				'recommendation'        => __( 'Choose a text/background pair with at least 3:1 contrast for qualifying large text. Darken the text, lighten it against a dark background, or adjust the background. If the design makes the text smaller, choose colors meeting 4.5:1 instead.', 'elavira' ),
				'verification_guidance' => __( 'Use a contrast tool to measure the rendered color pair and confirm the threshold appropriate to its actual size and weight. Check responsive sizes and relevant states, then re-audit.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content/style fix: adjust heading or text-block colors and typography settings. Code fix: update theme styles or responsive rules that change the text size or background.', 'elavira' ),
				'developer_guidance'    => __( 'Large text is at least 18 pt (24 CSS px), or 14 pt (about 18.67 CSS px) when bold. Do not round a failing contrast ratio up to the threshold.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.contrast.non_text_insufficient@1.0.0' => array(
				'title'                 => __( 'Essential visual contrast is too low', 'elavira' ),
				'summary'               => __( 'Elavira measured an essential visual part of a control or graphic below 3:1 contrast against its adjacent color.', 'elavira' ),
				'why_it_matters'        => __( 'A person with low vision may struggle to identify the control, its state, or information carried by the graphic.', 'elavira' ),
				'what_to_check'         => __( 'Locate the recorded component or graphical relationship and its foreground/background pair. Determine which visible part carries the essential information, such as a boundary needed to find a field. This does not mean every decorative border must meet a contrast threshold.', 'elavira' ),
				'recommendation'        => __( 'Change the essential indicator, boundary, fill or adjacent background so the relevant relationship reaches at least 3:1. Preserve a clear way to identify the control or state; adding a high-contrast decorative border elsewhere does not fix the affected information.', 'elavira' ),
				'verification_guidance' => __( 'Measure the essential visual part against its actual adjacent color. Confirm it reaches 3:1 and still identifies the control or information. Test relevant states separately, then re-audit the rendered state.', 'elavira' ),
				'wordpress_guidance'    => __( 'Style fix: adjust component border, icon, state-indicator or background colors where settings exist. Code fix: change the responsible theme or plugin CSS when the essential visual is generated there.', 'elavira' ),
				'developer_guidance'    => __( 'Apply non-text contrast to visual information needed to identify controls/states or understand graphics, accounting for applicable exceptions. Do not substitute text contrast measurements for the essential non-text relationship.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.contrast.cannot_determine@1.0.0'      => array(
				'guided_decision'       => 'contrast_review',
				'title'                 => __( 'Contrast needs manual measurement', 'elavira' ),
				'summary'               => __( 'Elavira could not reliably calculate contrast for this text or component. This is not a measured failure.', 'elavira' ),
				'why_it_matters'        => __( 'Text or essential controls may be difficult to distinguish even when complex rendering prevents a reliable automated measurement.', 'elavira' ),
				'what_to_check'         => __( 'Read the candidate type, required threshold and reason in Technical Details. Inspect the actual background, including images, gradients, transparency or overlapping layers. Measure the least contrasting relevant areas and states with an appropriate contrast tool; do not treat the missing ratio as a pass or a zero.', 'elavira' ),
				'recommendation'        => __( 'If testing confirms insufficient contrast, simplify the background or place the content on a solid backing, or adjust the text/essential indicator colors. Aim for at least 4.5:1 for ordinary text and 3:1 for qualifying large text or essential non-text visuals.', 'elavira' ),
				'verification_guidance' => __( 'Manually measure the effective color relationships across the affected content and relevant states. Confirm both applicability and the required ratio. Re-audit after changes; complex rendering may continue to need human review even when the colors are acceptable.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content/style fix: adjust a background image, overlay or block palette where available. Code fix: simplify layering or component styles when settings cannot produce reliable separation.', 'elavira' ),
				'developer_guidance'    => __( 'Do not guess effective colors from individual CSS tokens. The recorded reason explains a calculation limit; it does not establish contrast quality. Check text and non-text applicability separately.', 'elavira' ),
				'examples'              => array(),
			),
			'elavira.color.color_only_review@1.0.0'        => array(
				'title'                 => __( 'Error status may rely on color alone', 'elavira' ),
				'summary'               => __( 'Elavira found a control marked invalid without a referenced error message detected by this check. Check whether its status depends on color alone.', 'elavira' ),
				'why_it_matters'        => __( 'Someone who cannot distinguish the error color may miss which field needs attention or what action to take.', 'elavira' ),
				'what_to_check'         => __( 'Trigger this error in a safe test form. Ignoring color, can you identify the affected field and understand the error from text or another meaningful cue? Check the full page: an unrecorded message or other cue may already communicate it.', 'elavira' ),
				'recommendation'        => __( 'If color carries the error alone, add visible error text identifying the problem and how to respond. Associate that message with the field for assistive technology. Keep color as a supplementary cue rather than the only signal.', 'elavira' ),
				'verification_guidance' => __( 'Repeat the error test and check that its meaning is clear without depending on the color difference. Focus the field with a screen reader and confirm the error is available. Re-audit, then make the human decision about the cues.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: write useful error messages in the form settings. Code fix: expose and connect them in the form component when it only changes border or background color.', 'elavira' ),
				'developer_guidance'    => __( 'Missing referenced text is a bounded risk signal, not proof that the page has no visible non-color cue. Coordinate aria-invalid and the supported description/error relationship with the actual state.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'A red border is the only sign an email field is invalid', 'elavira' ),
						'consider'    => __( 'Show “Enter an email address in the format name@example.com” beside that field', 'elavira' ),
						'explanation' => __( 'Use a message that describes the actual validation problem and associate it with the field. The color can remain as an extra cue.', 'elavira' ),
					),
				),
			),
			'elavira.images.alt_quality_review@1.0.0'      => array(
				'title'                 => __( 'Image alternative needs a context check', 'elavira' ),
				'summary'               => __( 'Elavira found supplied image alternative text in a link, control or captioned context. A person must decide whether it fits this use; the alternative may already be appropriate.', 'elavira' ),
				'why_it_matters'        => __( 'An alternative can describe a picture yet omit what a link does, or repeat information a reader has already heard.', 'elavira' ),
				'what_to_check'         => __( 'Find the image using its filename and alt excerpt when recorded, then read the full alternative on the page. Is the image informative, decorative, functional, or showing meaningful text? For an image-only link, compare its destination with the name a screen reader announces. For a captioned image, decide whether the caption already communicates all relevant information.', 'elavira' ),
				'recommendation'        => __( 'For an image-only link, make the accessible alternative communicate the destination or action. “Envelope icon” may describe the picture without explaining the link; choose purpose-based wording when needed. If a linked image visibly says “View Fall Collection”, communicate those meaningful words and purpose. If useful text already names the same link and the image adds only decoration, alt="" can be correct. For informative images convey the relevant information; keep appropriate existing alternatives. For an image that names a button, communicate the button action. For a captioned image, use empty alt only when the caption or nearby text already supplies everything the image contributes; otherwise provide the missing information.', 'elavira' ),
				'verification_guidance' => __( 'Read or listen to the alternative in the full context. For a linked image, check the whole link name and compare it with the destination; for a decorative image, confirm no information or function is lost when it is skipped. Re-audit after changes, but a review finding can remain even when your chosen alternative is correct.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit the Image block alternative for this particular use. A Media Library change may not update existing blocks. Code fix: correct linked, featured or plugin-generated images when their alternatives come from a template.', 'elavira' ),
				'developer_guidance'    => __( 'Use recorded link kind, destination, alt state/excerpt, simple available name and paragraph context only when present. Excerpts are bounded and the simple name is not a guaranteed complete accessibility-tree name. Inspect ARIA/reference relationships on the rendered link; do not recommend redundant alt for every image inside a link.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( '<a href="/contact/"><img src="envelope.svg" alt="Envelope icon"></a>', 'elavira' ),
						'consider'    => __( '<a href="/contact/"><img src="envelope.svg" alt="Contact us"></a>', 'elavira' ),
						'explanation' => __( 'This change fits a link to contact information or a contact action. The alternative names what the link does, not merely its picture; choose wording for the actual destination.', 'elavira' ),
					),
					array(
						'instead_of'  => __( 'A linked image visibly says “View Fall Collection” but its alt is “Autumn leaves”', 'elavira' ),
						'consider'    => __( 'Use an alternative conveying “View Fall Collection”', 'elavira' ),
						'explanation' => __( 'Preserve the meaningful words and purpose. An appearance-only description loses the information used to choose this link.', 'elavira' ),
					),
					array(
						'instead_of'  => __( '<a href="/pricing/">View pricing<img src="arrow.svg" alt="Arrow pointing right"></a>', 'elavira' ),
						'consider'    => __( '<a href="/pricing/">View pricing<img src="arrow.svg" alt=""></a>', 'elavira' ),
						'explanation' => __( 'The useful text already names this link and the arrow adds only decoration. Empty alt avoids an unnecessary extra announcement.', 'elavira' ),
					),
				),
			),
			'elavira.images.filename_alt@1.0.0'            => array(
				'title'                 => __( 'Image alternative resembles a filename', 'elavira' ),
				'summary'               => __( 'Elavira found alternative text that resembles an image filename. Check whether that text actually communicates useful information here.', 'elavira' ),
				'why_it_matters'        => __( 'A filename such as a camera-generated number usually says little about an image or the action of a linked image.', 'elavira' ),
				'what_to_check'         => __( 'Compare the recorded alt excerpt with the image and its surrounding content. Is the filename itself meaningful information in this context, or was it copied automatically? If the image is a link or control, identify what activating it does; if it is decorative, ask whether it needs any announced text.', 'elavira' ),
				'recommendation'        => __( 'Replace an unhelpful filename with the relevant information for an informative image, or the action/destination for a functional image. Include meaningful words shown in an image. Use alt="" for a purely decorative image when no information or control name depends on it. Keep a filename only when it genuinely communicates the intended information.', 'elavira' ),
				'verification_guidance' => __( 'Read the full alternative in context and check it conveys what someone needs without seeing the image. For a link or button, check the announced name describes its actual function. Re-audit; the filename pattern alone cannot decide correctness.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: replace auto-filled alternatives in the Image block or Media Library for each relevant use. Code fix: stop import or template logic from using a filename as the default meaningful alternative.', 'elavira' ),
				'developer_guidance'    => __( 'Prefer native alt appropriate to this occurrence. Do not generate or approve replacement text automatically; verify the complete alternative rather than relying on the shortened excerpt.', 'elavira' ),
				'examples'              => array(
					array(
						'instead_of'  => __( 'alt="DSC_2048.jpg"', 'elavira' ),
						'consider'    => __( 'alt="Step-free entrance on the east side of the building"', 'elavira' ),
						'explanation' => __( 'This wording is useful only if that is the information this particular entrance photograph is intended to convey.', 'elavira' ),
					),
				),
			),
			'elavira.images.long_alt_review@1.0.0'         => array(
				'title'                 => __( 'Long image alternative needs a context check', 'elavira' ),
				'summary'               => __( 'Elavira found an extended, multi-sentence image alternative. Length alone does not make it incorrect.', 'elavira' ),
				'why_it_matters'        => __( 'A long alternative can be difficult to navigate or remember. Removing detail indiscriminately can also lose information the image is meant to communicate.', 'elavira' ),
				'what_to_check'         => __( 'Read the complete alternative on the page; the recorded excerpt may omit most of it. Does every detail help in this context? Would a chart, diagram or detailed illustration be easier to understand through nearby structured text or a table? There is no universal alt-text character limit that decides this finding.', 'elavira' ),
				'recommendation'        => __( 'If the alternative is unwieldy, keep a concise identification or purpose in alt and provide the important detail in accessible nearby text, a table or a linked detailed explanation. Preserve all relevant information. For an image used as a link or control, keep its action understandable; retain a longer alternative when it is appropriate.', 'elavira' ),
				'verification_guidance' => __( 'Read or listen to the short alternative and any detailed equivalent in sequence. Confirm the important information and relationships are preserved and the detailed explanation is easy to find and navigate. Re-audit, but judge usefulness rather than length alone.', 'elavira' ),
				'wordpress_guidance'    => __( 'Content fix: edit the Image block alternative and add the necessary explanation or table in nearby content. Code fix: ensure a template exposes and associates the detailed equivalent where the editor cannot.', 'elavira' ),
				'developer_guidance'    => __( 'Do not truncate alt to satisfy the heuristic. A concise alternative can point readers to a detailed equivalent; use actual text and semantic tables/headings for information that needs navigation.', 'elavira' ),
				'examples'              => array(),
			),
		);
		$aria_topic_contracts = array(
			'elavira.semantics.control_missing_name@1.0.0',
			'elavira.semantics.invalid_role@1.0.0',
			'elavira.semantics.required_state_missing@1.0.0',
			'elavira.semantics.state_consistency_review@1.0.0',
			'elavira.semantics.native_semantics_overridden@1.0.0',
			'elavira.aria.invalid_attribute@1.0.0',
			'elavira.aria.invalid_value@1.0.0',
			'elavira.aria.prohibited_attribute@1.0.0',
			'elavira.aria.required_attribute_missing@1.0.0',
			'elavira.aria.broken_id_reference@1.0.0',
			'elavira.aria.duplicate_id_reference@1.0.0',
			'elavira.aria.redundant_role@1.0.0',
		);
		foreach ( $aria_topic_contracts as $contract ) {
			$guidance[ $contract ]['learn_topic'] = 'aria_accessible_controls';
		}
		$useful_wordpress = array(
			'elavira.contrast.text_insufficient@1.0.0',
			'elavira.contrast.large_text_insufficient@1.0.0',
			'elavira.contrast.non_text_insufficient@1.0.0',
			'elavira.image.alt_missing@1.0.0',
			'elavira.structure.multiple_h1@1.0.0',
			'elavira.images.filename_alt@1.0.0',
			'elavira.images.long_alt_review@1.0.0',
		);
		foreach ( $guidance as $contract => &$entry ) {
			$entry['wordpress_guidance_useful'] = in_array( $contract, $useful_wordpress, true );
		}
		unset( $entry );
		return $guidance;
	}
}
